"c07",null,null,null,null,1,null,1,"||3-pole|60"],["100A 3-pole breaker (match the panel)","pc","c07",null,null,null,null,1,null,1,"||3-pole|100"],["Ceiling occupancy sensor (low voltage)","pc","c06",null,null,null,null,0,null,null,null],["Occupancy sensor power pack","pc","c06",null,null,null,null,0,null,null,null],["Emergency LED driver (battery backup)","pc","c06",null,null,null,null,0,null,null,null],["0-10V LED dimmer (commercial)","pc","c06",null,null,null,null,0,null,null,null]],"desc":["Confirm the exact model and number of spaces; use only breakers listed for this panel","Must match the panel brand/line — check the panel label before ordering","Cut length — type the exact feet","Two 12/2 circuits in one jacket — confirm the supplier stocks it","Type the exact feet (e.g. 65, 120, 185)","Copper SER — confirm availability/price before ordering; type the exact feet","Type the exact feet","Confirm the exact model and that the utility (Con Ed / O&R / PSEG) approves it — do not assume equipment is interchangeable","Hub must match the meter socket brand","Confirm voltage, brand and model before ordering"],"lines":[["Siemens","QP","Siemens QP",1],["Eaton","BR","Eaton BR",1],["Eaton","CH","Eaton CH",0],["Square D","Homeline","Square D Homeline",1],["Square D","QO","Square D QO",0]],"tpl":[["mtpl_rough","Residential rough-in","res",[["7cde6580",4],["d8625203",6],["b5af7e5a",1],["ef01f98e",1],["6307a48a",40],["781a65e0",10],["d24d17ac",2],["e8b3747a",4],["27bc60f7",10],["829dff2d",4],["38928c0b",1],["987eb5dc",1],["3034da5c",1],["194a0c34",1],["f68c6e32",1]]],["mtpl_finish","Residential finish","res",[["ca844bb2",40],["a991d2c7",10],["5bd31498",4],["46f694f2",2],["d4e6d805",2],["42adc168",20],["f679c689",6],["519689cf",4],["6934aba5",30],["88e19e19",6],["8e718a26",20],["fce51b32",20],["299d8d87",3],["beb6c194",4],["909d794f",2],["ccfd0ed8",1]]],["mtpl_house","Complete house (rough + finish)","res",[["7cde6580",4],["d8625203",6],["b5af7e5a",1],["ef01f98e",1],["6307a48a",40],["781a65e0",10],["d24d17ac",2],["e8b3747a",4],["27bc60f7",10],["829dff2d",4],["38928c0b",1],["987eb5dc",1],["3034da5c",1],["194a0c34",1],["f68c6e32",1],["ca844bb2",40],["a991d2c7",10],["5bd31498",4],["46f694f2",2],["d4e6d805",2],["42adc168",20],["f679c689",6],["519689cf",4],["6934aba5",30],["88e19e19",6],["8e718a26",20],["fce51b32",20],["299d8d87",3],["beb6c194",4],["909d794f",2],["ccfd0ed8",1]]],["mtpl_apt","Apartment (one unit)","res",[["7cde6580",2],["d8625203",3],["6307a48a",20],["781a65e0",4],["27bc60f7",6],["ca844bb2",18],["a991d2c7",6],["46f694f2",3],["42adc168",10],["6934aba5",12],["8e718a26",18],["fce51b32",10],["299d8d87",2],["829dff2d",2],["987eb5dc",1]]],["mtpl_reno","Renovation (old work)","res",[["7cde6580",1],["d8625203",2],["943e2797",15],["4c811949",4],["f4e9ae43",3],["d827cd71",2],["8b3c7ded",10],["15349825",10],["ca844bb2",12],["46f694f2",2],["42adc168",6],["fce51b32",8],["987eb5dc",1]]],["mtpl_service","Service upgrade (200A)","res",[["73f75a24",1],["b5ae31e5",30],["ef1b7e82",1],["ce514963",1],["f6f72662",2],["9e338d60",1],["0c5ed5b3",1],["c609a519",2],["ee8b89ff",2],["c9440d99",40],["7913bd23",1],["17583769",1],["25abe3ac",1],["9e50c398",2]]],["mtpl_panel","Panel replacement","res",[["c0bd041e",1],["8f68745c",1],["cc6f840a",1],["25abe3ac",1],["3034da5c",1],["987eb5dc",1],["b2ca142e",20],["e9d42d9d",4],["9d215fb1",10],["17583769",1]]],["mtpl_com","Commercial job (light commercial)","com",[["f176a1cc",6],["4300fbc3",2],["fe23933a",100],["a1b60689",30],["4c65964a",30],["080126bc",20],["b9c6a1ed",40],["5ed2be7b",20],["e1878125",40],["2845084e",10],["66f459b2",4],["d84a2bb5",2],["65d620fd",20],["c10178c8",20],["d93a2e75",1],["4df6a4fb",5],["0293d09f",4]]]]}$plan$::jsonb; r jsonb; nm text; hh text; c text; n_new int := 0; n_upd int := 0; n_mrg int := 0; n_skip int := 0;
        tid text; its jsonb; nowms bigint := (extract(epoch from now())*1000)::bigint; at text[];
begin
  create temp table _s on commit drop as
    select id, left(md5(lower(btrim(data->>'name'))), 8) h, data from public.records where coll = 'stock' and not deleted and jsonb_typeof(data) = 'object';
  -- 1. new materials (only if no material has that name already)
  for r in select value from jsonb_array_elements(p->'new') loop
    nm := r->>0; hh := left(md5(lower(btrim(nm))), 8);
    if exists (select 1 from _s where _s.h = hh or (jsonb_typeof(_s.data->'aka') = 'array' and _s.data->'aka' ? nm)) then continue; end if;
    at := case when r->>10 is null then null else string_to_array(r->>10, '|') end;
    insert into public.records(coll, id, data, deleted, updated_by, updated_at)
    values ('stock', 'c2_' || hh, jsonb_strip_nulls(jsonb_build_object('id', 'c2_' || hh, 'name', nm, 'unit', r->>1, 'qty', 0, 'min', 0, 'qv', 0,
            'sec', p->'cats'->(r->>2)->>0, 'cat', p->'cats'->(r->>2)->>1, 'fam', r->>3, 'vl', r->>4, 'pkg', r->>5, 'ft', (r->>6)::numeric,
            'verify', case when (r->>7) = '1' then true end, 'brand', r->>8, 'desc', case when r->>9 is not null then p->'desc'->>((r->>9)::int) end,
            'at', case when at is null then null else jsonb_strip_nulls(jsonb_build_object('brand', nullif(at[1],''), 'line', nullif(at[2],''), 'type', nullif(at[3],''),
                        'amps', case when coalesce(at[4],'') <> '' then at[4]::numeric end)) end,
            'crev', 1, 'cv', 2, 'cedBy', 'catalog-v2', 'cedAt', nowms)), false, 'catalog-v2', now())
    on conflict (coll, id) do nothing;
    if found then n_new := n_new + 1; end if;
    insert into _s select 'c2_' || hh, hh, data from public.records where coll = 'stock' and id = 'c2_' || hh;
  end loop;
  -- 1b. panels and breakers for each manufacturer line (generic names, no model numbers; must match the panel)
  for r in select value from jsonb_array_elements(p->'lines') loop
    declare b text := r->>0; l text := r->>1; pre text := r->>2; nm2 text; a int; spec jsonb;
    begin
      for spec in select value from jsonb_array_elements(
          '[["100A main breaker panel (indoor)","r06",null,null,1],["200A main breaker panel (indoor)","r06",null,null,1],["200A main breaker panel (outdoor 3R)","r06",null,null,1],["125A main lug sub-panel","r06",null,null,1],["200A main lug panel","r06",null,null,1]]'::jsonb
          || (select jsonb_agg(jsonb_build_array(x || 'A 1-pole breaker', 'r07', '1-pole', x, 0)) from unnest(array[15,20,30]) x)
          || (select jsonb_agg(jsonb_build_array(x || 'A 2-pole breaker', 'r07', '2-pole', x, 0)) from unnest(array[15,20,25,30,40,50,60,70,80,90,100,125]) x)
          || (select jsonb_agg(jsonb_build_array(x || 'A AFCI breaker (combination)', 'r07', 'AFCI', x, 0)) from unnest(array[15,20]) x)
          || (select jsonb_agg(jsonb_build_array(x || 'A GFCI breaker 1-pole', 'r07', 'GFCI', x, 0)) from unnest(array[15,20]) x)
          || (select jsonb_agg(jsonb_build_array(x || 'A dual function AFCI/GFCI breaker', 'r07', 'Dual function', x, 0)) from unnest(array[15,20]) x)
          || (select jsonb_agg(jsonb_build_array(x || 'A 2-pole GFCI breaker', 'r07', 'GFCI', x, 0)) from unnest(array[30,50]) x)
          || '[["15A/15A tandem breaker","r07","Tandem",15,0],["20A/20A tandem breaker","r07","Tandem",20,0]]'::jsonb
          || case when (r->>3) = '1' then '[["quad breaker (two 2-pole) — pick amps when ordering","r07","Quad",null,1]]'::jsonb else '[]'::jsonb end
          || (select jsonb_agg(jsonb_build_array(x || 'A main breaker (replacement — verify panel)', 'r07', 'Main', x, 1)) from unnest(array[100,150,200]) x)) loop
        nm2 := pre || ' ' || (spec->>0); hh := left(md5(lower(btrim(nm2))), 8);
        if exists (select 1 from _s where _s.h = hh) then continue; end if;
        insert into public.records(coll, id, data, deleted, updated_by, updated_at)
        values ('stock', 'c2_' || hh, jsonb_strip_nulls(jsonb_build_object('id', 'c2_' || hh, 'name', nm2, 'unit', 'pc', 'qty', 0, 'min', 0, 'qv', 0,
                'sec', 'res', 'cat', p->'cats'->(spec->>1)->>1, 'brand', b, 'verify', case when spec->>1 = 'r06' or (spec->>4) = '1' then true end,
                'desc', p->'desc'->>(case when spec->>1 = 'r06' then 0 else 1 end),
                'at', jsonb_strip_nulls(jsonb_build_object('brand', b, 'line', l, 'type', spec->>2, 'amps', (spec->>3)::numeric)),
                'crev', 1, 'cv', 2, 'cedBy', 'catalog-v2', 'cedAt', nowms)), false, 'catalog-v2', now())
        on conflict (coll, id) do nothing;
        if found then n_new := n_new + 1; end if;
        insert into _s select 'c2_' || hh, hh, data from public.records where coll = 'stock' and id = 'c2_' || hh;
      end loop;
    end;
  end loop;
  -- 2. what changes on each material
  create temp table _p (h text primary key, sec text, cat text, fam text, vl text, pkg text, ft numeric, fav boolean, hide boolean) on commit drop;
  for c in select jsonb_object_keys(p->'map') loop
    insert into _p(h, sec, cat) select x, p->'cats'->c->>0, p->'cats'->c->>1 from unnest(string_to_array(p->'map'->>c, ',')) x on conflict (h) do nothing;
  end loop;
  update _p set fav = true where h in (select jsonb_array_elements_text(p->'fav'));
  update _p set hide = true where h in (select jsonb_array_elements_text(p->'hide'));
  insert into _p(h, fav) select x, true from jsonb_array_elements_text(p->'fav') x where not exists (select 1 from _p where _p.h = x) on conflict do nothing;
  with ch as (
    select s.id, s.data, s.data || jsonb_strip_nulls(jsonb_build_object('sec', _p.sec, 'cat', _p.cat, 'fav', _p.fav))
             || case when _p.hide and coalesce(public._num(s.data->>'qty'), 0) = 0 then '{"hidden":true}'::jsonb else '{}'::jsonb end || '{"cv":2}'::jsonb nd
      from _s s join _p on _p.h = s.h)
  update public.records r set data = ch.nd || jsonb_build_object('crev', coalesce(public._num(ch.data->>'crev')::int, 0) + 1, 'cedBy', 'catalog-v2', 'cedAt', nowms),
         updated_by = 'catalog-v2', updated_at = now()
    from ch where r.coll = 'stock' and r.id = ch.id and (ch.nd - 'cv' - 'crev' - 'cedBy' - 'cedAt') is distinct from (ch.data - 'cv' - 'crev' - 'cedBy' - 'cedAt');
  get diagnostics n_upd = row_count;
  -- 3. clear duplicates (only those with nothing counted in the garage)
  for r in select value from jsonb_array_elements(p->'merge') loop
    declare d record; t record;
    begin
      select * into d from public.records where coll = 'stock' and not deleted and left(md5(lower(btrim(data->>'name'))), 8) = r->>0 limit 1;
      select * into t from public.records where coll = 'stock' and not deleted and left(md5(lower(btrim(data->>'name'))), 8) = r->>1 limit 1;
      if d.id is null or t.id is null or d.id = t.id or coalesce(d.data->>'mergedInto','') <> '' then continue; end if;
      if coalesce(public._num(d.data->>'qty'), 0) <> 0 then n_skip := n_skip + 1; continue; end if;   -- a person decides (Manage Materials)
      update public.records set data = data || jsonb_build_object('hidden', true, 'mergedInto', t.id, 'crev', coalesce(public._num(data->>'crev')::int, 0) + 1,
             'cedBy', 'catalog-v2', 'cedAt', nowms), updated_by = 'catalog-v2', updated_at = now() where coll = 'stock' and id = d.id;
      update public.records set data = data || jsonb_build_object('aka', (select coalesce(jsonb_agg(distinct x), '[]'::jsonb) from (
               select jsonb_array_elements_text(case when jsonb_typeof(data->'aka') = 'array' then data->'aka' else '[]'::jsonb end) x union select d.data->>'name') q)),
             updated_by = 'catalog-v2', updated_at = now() where coll = 'stock' and id = t.id;
      n_mrg := n_mrg + 1;
    end;
  end loop;
  -- 4. templates (editable later in Manage Materials; never overwritten once they exist)
  for r in select value from jsonb_array_elements(p->'tpl') loop
    tid := r->>0;
    if exists (select 1 from public.records where coll = 'mtpl' and id = tid) then continue; end if;
    select coalesce(jsonb_agg(jsonb_build_object('sid', s.id, 't', s.data->>'name', 'q', (x->>1)::numeric, 'u', s.data->>'unit') order by o), '[]'::jsonb) into its
      from jsonb_array_elements(r->3) with ordinality a(x, o)
      join lateral (select id, data from public.records where coll = 'stock' and not deleted and left(md5(lower(btrim(data->>'name'))), 8) = x->>0 limit 1) s on true;
    insert into public.records(coll, id, data, deleted, updated_by, updated_at)
    values ('mtpl', tid, jsonb_build_object('id', tid, 'name', r->>1, 'sec', r->>2, 'items', its, 'by', 'catalog-v2', 'ts', nowms), false, 'catalog-v2', now());
  end loop;
  insert into public.server_config(k, v) values ('catalog_version', '2') on conflict (k) do update set v = '2';
  raise notice 'catalog v2: % new, % updated, % duplicates hidden, % duplicates left for a person (counted)', n_new, n_upd, n_mrg, n_skip;
end $cat$;
